let data=[]; let activeLc=null; let currentUser=null; let csrfToken=''; let users=[]; let assignableUsers=[]; let openTasks=[];
const $=s=>document.querySelector(s);
const fmtDate=d=>d?new Intl.DateTimeFormat('de-DE').format(new Date(d+'T00:00:00')):'–';
const money=(n,c)=>n==null?'–':new Intl.NumberFormat('de-DE',{style:'currency',currency:c||'EUR'}).format(n);
const fileSize=n=>n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(1)} MB`;
async function json(url,options={}){options.headers=options.headers||{};if(csrfToken&&options.method&&options.method!=='GET')options.headers['X-CSRF-TOKEN']=csrfToken;const r=await fetch(url,options);if(r.status===401){location.replace('/login.html');throw new Error('Anmeldung erforderlich.')}if(!r.ok){let message=`HTTP ${r.status}`;try{message=(await r.json()).error||message}catch(e){}throw new Error(message)}return r.status===204?null:r.json()}
async function load(){try{const [lcs,statuses]=await Promise.all([json('/api/lcs'),json('/api/lcs/dossier-status').catch(()=>[])]),byId=new Map(statuses.map(status=>[status.lcId,status]));data=lcs.map(lc=>({...lc,dossierStatus:byId.get(lc.id)||null}));render();await Promise.all([loadHistory(),loadDashboardDrafts()])}catch(e){$('#list').innerHTML='<div class="empty">API nicht erreichbar.</div>'}}
async function loadDashboardDrafts(){const rows=(await json('/api/training').catch(()=>[])).filter(item=>item.status==='DRAFT');const panel=$('#trainingDraftPanel');panel.classList.toggle('hidden',!rows.length);$('#trainingDraftList').innerHTML=rows.length?rows.slice(0,10).map(item=>`<div class="draft-row"><div><b>${esc(item.filename)}</b><small>${esc(item.messageType||'Format unbekannt')} · begonnen ${new Intl.DateTimeFormat('de-DE',{dateStyle:'short',timeStyle:'short'}).format(new Date(item.createdAt))}</small></div><span class="badge">Training – Entwurf</span><button type="button" class="secondary" data-training-id="${item.id}">Training fortsetzen</button></div>`).join(''):'';document.querySelectorAll('[data-training-id]').forEach(button=>button.onclick=async()=>{$('#trainingDialog').showModal();await openTrainingSession(button.dataset.trainingId)})}
async function loadHistory(){const rows=await json('/api/imports').catch(()=>[]);$('#importHistory').innerHTML=rows.length?rows.map(x=>`<div class="history-row"><span class="import-status ${x.status.toLowerCase()}">${x.status==='SUCCESS'?'Erfolgreich':'Abgelehnt'}</span><div><b>${esc(x.filename)}</b><small>${esc(x.messageType||'–')} · ${esc(x.reference||'ohne Referenz')}</small></div><div>${esc(x.message||'')}</div><small>${new Intl.DateTimeFormat('de-DE',{dateStyle:'short',timeStyle:'short'}).format(new Date(x.importedAt))}</small></div>`).join(''):'<div class="empty compact">Noch keine Importe protokolliert.</div>'}
function daysUntil(date){if(!date)return 99999;const target=new Date(date+'T00:00:00'),today=new Date();today.setHours(0,0,0,0);return Math.round((target-today)/864e5)}
function deadlineInfo(lc){if(['CLOSED','EXPIRED'].includes(lc.status))return{level:'neutral',text:statusLabel(lc.status),score:90000};const expiry=daysUntil(lc.expiryDate),shipment=daysUntil(lc.latestShipmentDate),followUp=daysUntil(lc.followUpDate);if(expiry<0)return{level:'overdue',text:`Ablauf seit ${Math.abs(expiry)} Tagen`,score:-40000+expiry};if(shipment<0)return{level:'overdue',text:`Versandfrist seit ${Math.abs(shipment)} Tagen`,score:-30000+shipment};if(followUp<0)return{level:'overdue',text:`Wiedervorlage seit ${Math.abs(followUp)} Tagen`,score:-20000+followUp};if(followUp===0)return{level:'urgent',text:'Wiedervorlage heute',score:-10000};if(expiry<=7)return{level:'urgent',text:`Ablauf in ${expiry} Tagen`,score:expiry};if(shipment<=7)return{level:'urgent',text:`Versandfrist in ${shipment} Tagen`,score:100+shipment};if(followUp<=7)return{level:'urgent',text:`Wiedervorlage in ${followUp} Tagen`,score:200+followUp};if(expiry<=30)return{level:'soon',text:`Ablauf in ${expiry} Tagen`,score:1000+expiry};if(followUp<99999)return{level:'normal',text:`Wiedervorlage ${fmtDate(lc.followUpDate)}`,score:2000+followUp};return{level:'normal',text:lc.expiryDate?`Ablauf ${fmtDate(lc.expiryDate)}`:'Keine Ablauffrist',score:50000+expiry}}
function render(){const q=$('#search').value.toLowerCase(),traffic=$('#lcTrafficFilter').value,owner=$('#lcOwnerFilter').value,sort=$('#lcSort').value,username=(currentUser?.username||'').toLowerCase();let rows=data.filter(x=>[x.reference,x.applicant,x.beneficiary,x.assignedTo].join(' ').toLowerCase().includes(q)&&(!traffic||x.dossierStatus?.status===traffic)&&(!owner||(owner==='mine'?String(x.assignedTo||'').toLowerCase()===username:!x.assignedTo)));rows.sort((a,b)=>sort==='reference'?String(a.reference).localeCompare(String(b.reference)):sort==='expiry'?daysUntil(a.expiryDate)-daysUntil(b.expiryDate):(a.dossierStatus?.status==='RED'?0:a.dossierStatus?.status==='YELLOW'?1:2)-(b.dossierStatus?.status==='RED'?0:b.dossierStatus?.status==='YELLOW'?1:2)||deadlineInfo(a).score-deadlineInfo(b).score);$('#count').textContent=data.length;$('#docs').textContent=data.reduce((n,x)=>n+(x.requiredDocuments?.length||0),0);$('#due').textContent=data.filter(x=>{const days=Math.min(daysUntil(x.expiryDate),daysUntil(x.followUpDate));return days>=0&&days<=30}).length;$('#list').innerHTML=rows.length?rows.map(x=>{const review=x.dossierStatus,color=(review?.status||'YELLOW').toLowerCase(),label={GREEN:'Prüfung erfüllt',YELLOW:'Hinweise offen',RED:'Abweichungen'}[review?.status]||'Prüfung offen',deadline=deadlineInfo(x);return `<div class="row dossier-row" data-id="${x.id}"><span class="dossier-light tls-${color}" title="${label}"><i class="red"></i><i class="yellow"></i><i class="green"></i></span><div><strong>${esc(x.reference)}</strong><span class="muted">${esc(statusLabel(x.status||'RECEIVED'))}</span></div><div><strong>${esc(x.beneficiary||'–')}</strong><span class="muted">Beneficiary</span></div><div><strong>${esc(x.applicant||'–')}</strong><span class="muted">Applicant</span></div><div><strong class="deadline ${deadline.level}">${esc(deadline.text)}</strong><span class="muted">Fristen</span></div><div class="dossier-numbers"><strong>${review?.documents??0} Dokumente</strong><span class="muted">${esc(x.assignedTo||'Nicht zugewiesen')} · ${review?.discrepancies??0} Abw. · ${review?.warnings??0} Hinweise</span></div><div class="amount"><strong>${money(x.amount,x.currency)}</strong><span class="muted">Amount</span></div></div>`}).join(''):'<div class="empty">Keine passenden Akkreditive.</div>';document.querySelectorAll('.row').forEach(r=>r.onclick=()=>show(r.dataset.id))}
async function show(id){const x=data.find(v=>v.id===id);if(!x)return;activeLc=x;const [amendments,documents,review]=await Promise.all([json(`/api/lcs/${id}/amendments`).catch(()=>[]),json(`/api/lcs/${id}/documents`).catch(()=>[]),json(`/api/lcs/${id}/document-checks`).catch(()=>null)]);const fields=[['Applicant',x.applicant],['Beneficiary',x.beneficiary],['Issuing Bank',x.issuingBank],['Advising Bank',x.advisingBank],['Issue Date',fmtDate(x.issueDate)],['Latest Shipment',fmtDate(x.latestShipmentDate)],['Expiry',fmtDate(x.expiryDate)],['Expiry Place',x.expiryPlace],['Amount',money(x.amount,x.currency)]];$('#detail').classList.remove('hidden');$('#detail').innerHTML=`<div class="panelhead"><div><h2>${esc(x.reference)}</h2><p>Letter of Credit · <span class="badge">${esc(statusLabel(x.status))}</span></p></div><div class="header-actions"><button id="editLc" class="secondary">Bearbeiten</button><button id="closeDetail">Schließen</button></div></div><div class="detailbody"><div class="grid">${fields.map(f=>`<div class="card"><small>${f[0]}</small><b>${esc(f[1]||'–')}</b></div>`).join('')}</div><div class="sectionhead"><div><h3>Dokumentenakte</h3><p>Hochgeladene Dokumente und strukturierte Metadaten</p></div><button id="uploadBtn">+ Dokument hochladen</button></div>${renderDocuments(documents)}<div class="sectionhead"><div><h3>Automatische Prüfung</h3><p>Erste regelbasierte Vorprüfung – fachliche Endprüfung bleibt erforderlich.</p></div><button id="refreshChecks" class="secondary">Neu prüfen</button></div>${renderReview(review)}<div class="docs"><h3>Erforderliche Dokumente laut LC</h3>${x.requiredDocuments?.length?`<ul>${x.requiredDocuments.map(d=>`<li>□ ${esc(d)}</li>`).join('')}</ul>`:'<p>Keine Dokumentenanforderungen erkannt.</p>'}</div><div class="docs"><h3>Amendment-Historie</h3>${amendments.length?amendments.map(a=>`<div class="card"><b>Amendment ${esc(a.amendmentNumber||'–')}</b><br><small>${fmtDate(a.amendmentDate)} · Expiry ${fmtDate(a.newExpiryDate)} · Shipment ${fmtDate(a.newLatestShipmentDate)}${a.amountIncrease?' · + '+money(a.amountIncrease,x.currency):''}${a.amountDecrease?' · − '+money(a.amountDecrease,x.currency):''}</small></div>`).join(''):'<p>Noch keine Amendments.</p>'}</div></div>`;$('#editLc').onclick=openEdit;$('#closeDetail').onclick=()=>$('#detail').classList.add('hidden');$('#uploadBtn').onclick=()=>{$('#uploadForm').reset();$('#uploadError').textContent='';$('#uploadDialog').showModal()};$('#refreshChecks').onclick=()=>show(id);$('#detail').scrollIntoView({behavior:'smooth',block:'start'})}
const showLcBase=show;show=async function(id){await showLcBase(id);const entries=Object.entries(activeLc?.additionalFields||{});if(entries.length){const section=document.createElement('div');section.className='docs additional-details';section.innerHTML=`<h3>Weitere Angaben</h3><div class="grid">${entries.map(([name,value])=>`<div class="card"><small>${esc(name)}</small><b>${esc(value)}</b></div>`).join('')}</div>`;$('#detail .detailbody').append(section)}};
function documentCategory(type){if(['COMMERCIAL_INVOICE','PACKING_LIST','BILL_OF_EXCHANGE'].includes(type))return['Handelsdokumente','Rechnung, Packliste und Wechsel'];if(['BILL_OF_LADING','AIR_WAYBILL','ROAD_CONSIGNMENT_NOTE','COURIER_RECEIPT'].includes(type))return['Transportdokumente','Fracht- und Versandnachweise'];if(['CERTIFICATE_OF_ORIGIN','INSPECTION_CERTIFICATE','BENEFICIARY_CERTIFICATE','QUALITY_CERTIFICATE'].includes(type))return['Zertifikate','Ursprung, Inspektion und Qualität'];if(type==='INSURANCE_CERTIFICATE')return['Versicherung','Versicherungsnachweise'];return['Anlagen','Sonstige Dokumente und Annexe']}
function documentRow(d){const editData=`data-document-edit="${d.id}" data-document-name="${esc(d.originalFilename)}" data-document-type="${d.documentType}" data-document-date="${d.documentDate||''}" data-document-amount="${d.amount??''}" data-document-currency="${esc(d.currency||'')}"`;return `<div class="document-row"><div class="file-icon">${fileExtension(d.originalFilename)}</div><a class="document-download" href="${d.downloadUrl}"><b>${esc(d.originalFilename)}</b><small>${esc(d.typeLabel)} · ${fileSize(d.fileSize)} · gespeichert ${new Intl.DateTimeFormat('de-DE',{dateStyle:'short',timeStyle:'short'}).format(new Date(d.uploadedAt))}</small><small class="extraction ${d.extractionStatus?.toLowerCase()}">${extractionLabel(d.extractionStatus)}${d.extractedDocumentNumber?' · Nr. '+esc(d.extractedDocumentNumber):''}${d.extractedReference?' · LC '+esc(d.extractedReference):''}</small></a><div class="document-meta"><span>${fmtDate(d.documentDate)}</span>${d.amount!=null?`<small>${money(d.amount,d.currency||activeLc.currency)}</small>`:''}${d.extractedAmount!=null&&d.amount!==d.extractedAmount?`<small>Erkannt: ${money(d.extractedAmount,d.extractedCurrency||activeLc.currency)}</small>`:''}${currentUser?.role!=='VIEWER'?`<div class="document-actions"><button type="button" class="secondary document-edit" ${editData}>Bearbeiten</button><button type="button" class="danger document-delete" data-document-id="${d.id}" data-document-name="${esc(d.originalFilename)}">Löschen</button></div>`:''}</div></div>`}
function renderDocuments(documents){if(!documents.length)return '<div class="empty compact">Noch keine Dokumente in dieser LC-Akte.</div>';const groups=new Map();documents.forEach(document=>{const category=documentCategory(document.documentType),key=category[0];if(!groups.has(key))groups.set(key,{title:key,subtitle:category[1],documents:[]});groups.get(key).documents.push(document)});return `<div class="dossier-overview"><div class="dossier-summary"><b>${documents.length} Dokument${documents.length===1?'':'e'} in dieser LC-Akte</b><small>${groups.size} Aktenbereich${groups.size===1?'':'e'}</small></div>${[...groups.values()].map(group=>`<section class="dossier-section"><div class="dossier-section-head"><div><h4>${group.title}</h4><small>${group.subtitle}</small></div><span>${group.documents.length}</span></div><div class="document-list">${group.documents.map(documentRow).join('')}</div></section>`).join('')}</div>`}
async function deleteDocument(button){if(!activeLc||!confirm(`Dokument „${button.dataset.documentName}“ aus dieser LC-Akte löschen?`))return;button.disabled=true;try{await json(`/api/lcs/${activeLc.id}/documents/${button.dataset.documentId}`,{method:'DELETE'});await show(activeLc.id)}catch(e){alert('Dokument konnte nicht gelöscht werden: '+e.message);button.disabled=false}}
function documentTypeOptions(selected){return [['COMMERCIAL_INVOICE','Commercial Invoice'],['PACKING_LIST','Packing List'],['BILL_OF_LADING','Bill of Lading'],['AIR_WAYBILL','Air Waybill'],['ROAD_CONSIGNMENT_NOTE','CMR / Road Consignment Note'],['CERTIFICATE_OF_ORIGIN','Certificate of Origin'],['INSURANCE_CERTIFICATE','Insurance Certificate'],['INSPECTION_CERTIFICATE','Inspection Certificate'],['BILL_OF_EXCHANGE','Bill of Exchange / Draft'],['BENEFICIARY_CERTIFICATE',"Beneficiary's Certificate"],['QUALITY_CERTIFICATE','Quality / Analysis Certificate'],['COURIER_RECEIPT','Courier Receipt'],['ANNEX','Annex / Anlage'],['OTHER','Other']].map(([value,label])=>`<option value="${value}"${value===selected?' selected':''}>${label}</option>`).join('')}
function openDocumentEdit(button){let dialog=$('#documentEditDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='documentEditDialog';dialog.innerHTML='<form id="documentEditForm"><div class="dialoghead"><div><h2>Dokumentdaten bearbeiten</h2><p id="documentEditName"></p></div><button type="button" class="ghost document-edit-close">×</button></div><input type="hidden" name="id"><div class="form-grid"><label class="wide">Dokumenttyp<select name="type" required></select></label><label>Dokumentdatum<input name="documentDate" type="date"></label><label>Betrag<input name="amount" type="number" min="0" step="0.01"></label><label>Währung<input name="currency" maxlength="3" placeholder="EUR"></label></div><div id="documentEditError" class="error"></div><div class="actions"><button type="button" class="secondary document-edit-close">Abbrechen</button><button type="submit">Änderungen speichern</button></div></form>';document.body.append(dialog);dialog.querySelectorAll('.document-edit-close').forEach(x=>x.onclick=()=>dialog.close());$('#documentEditForm').onsubmit=saveDocumentEdit}const form=$('#documentEditForm');form.elements.id.value=button.dataset.documentEdit;form.elements.type.innerHTML=documentTypeOptions(button.dataset.documentType);form.elements.documentDate.value=button.dataset.documentDate;form.elements.amount.value=button.dataset.documentAmount;form.elements.currency.value=button.dataset.documentCurrency;$('#documentEditName').textContent=button.dataset.documentName;$('#documentEditError').textContent='';dialog.showModal()}
async function saveDocumentEdit(event){event.preventDefault();const form=event.target,payload=Object.fromEntries(new FormData(form).entries()),id=payload.id;delete payload.id;payload.documentDate=payload.documentDate||null;payload.amount=payload.amount===''?null:Number(payload.amount);payload.currency=payload.currency||null;try{await json(`/api/lcs/${activeLc.id}/documents/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});$('#documentEditDialog').close();await show(activeLc.id)}catch(e){$('#documentEditError').textContent='Speichern fehlgeschlagen: '+e.message}}
function extractionLabel(status){return ({GENERATED:'Im LC-Manager erstellt',EXTRACTED:'Text automatisch ausgelesen',OCR_EXTRACTED:'Scan per OCR ausgelesen',NO_TEXT:'Auch per OCR kein Text erkannt',OCR_UNAVAILABLE:'OCR ist derzeit nicht verfügbar',UNSUPPORTED:'Format nicht auslesbar',FAILED:'Auslesen oder OCR fehlgeschlagen',NOT_PROCESSED:'Noch nicht verarbeitet'})[status]||status||'Nicht verarbeitet'}
function renderReview(review){if(!review)return '<div class="empty compact">Prüfung konnte nicht geladen werden.</div>';return reviewGate(review)+`<div class="review-summary"><span class="summary discrepancy">${review.discrepancies} Abweichungen</span><span class="summary warning">${review.warnings} offene Hinweise</span><span class="summary passed">${review.passed} erfüllt</span></div><div class="check-list">${review.results.map(r=>`<div class="check ${r.severity.toLowerCase()}"><span>${r.severity==='OK'?'✓':r.severity==='WARNING'?'!':'×'}</span><div><b>${label(r.severity)} · ${esc(r.message)}</b>${r.lcCondition?`<small class="check-source"><strong>LC-Bedingung</strong>${esc(r.lcCondition)}</small>`:''}${r.documentName||r.documentEvidence?`<small class="check-source"><strong>Fundstelle${r.documentName?' in '+esc(r.documentName):''}</strong>${esc(r.documentEvidence||'–')}</small>`:''}${r.reviewDecision?`<small class="check-source"><strong>Manuell geprüft</strong>${r.reviewDecision==='ACCEPTED'?'Als erfüllt bestätigt':'Abweichung bestätigt'} · ${esc(r.reviewedBy)} · ${new Intl.DateTimeFormat('de-DE',{dateStyle:'short',timeStyle:'short'}).format(new Date(r.reviewedAt))}${r.reviewComment?' · '+esc(r.reviewComment):''}</small>`:''}${currentUser?.role!=='VIEWER'&&(r.severity!=='OK'||r.reviewDecision)?`<div class="review-actions"><button type="button" class="secondary" data-check-decision="ACCEPTED" data-check-code="${esc(r.code)}" data-check-document="${esc(r.documentName||'')}">${r.reviewDecision?'Entscheidung ändern: erfüllt':'Als erfüllt bestätigen'}</button><button type="button" class="danger" data-check-decision="CONFIRMED_DISCREPANCY" data-check-code="${esc(r.code)}" data-check-document="${esc(r.documentName||'')}">${r.reviewDecision?'Entscheidung ändern: Abweichung':'Abweichung bestätigen'}</button></div>`:''}</div></div>`).join('')}</div>`}
async function decideCheck(findingCode,documentName,decision){const comment=prompt('Optionaler Prüfvermerk:');if(comment===null)return;await json(`/api/lcs/${activeLc.id}/document-checks/decisions`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({findingCode,documentName,decision,comment})});await show(activeLc.id)}
function downloadCheckReport(){location.href=`/api/lcs/${activeLc.id}/document-checks/report`}
document.addEventListener('click',event=>{const decision=event.target.closest('[data-check-decision]');if(decision)decideCheck(decision.dataset.checkCode,decision.dataset.checkDocument,decision.dataset.checkDecision);const deletion=event.target.closest('[data-document-id]');if(deletion)deleteDocument(deletion);const edit=event.target.closest('[data-document-edit]');if(edit)openDocumentEdit(edit)});
function label(s){return s==='OK'?'Erfüllt':s==='WARNING'?'Hinweis':'Abweichung'}
function statusLabel(s){return ({RECEIVED:'Eingegangen',ACTIVE:'Aktiv',AMENDED:'Geändert',DOCUMENTS_PRESENTED:'Dokumente eingereicht',EXPIRED:'Abgelaufen',CLOSED:'Abgeschlossen'})[s]||s}
function fileExtension(name){const x=(name.split('.').pop()||'FILE').toUpperCase();return x.length<=4?x:'FILE'}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function loadSwiftFile(inputId,textareaId,nameId,errorId){const input=$(inputId),file=input.files?.[0];if(!file)return;if(file.size>1048576){input.value='';$(nameId).textContent='TXT oder SWIFT, maximal 1 MB';$(errorId).textContent='Die Datei ist größer als 1 MB.';return}try{$(textareaId).value=await file.text();$(nameId).textContent=`${file.name} · ${fileSize(file.size)}`;$(errorId).textContent=''}catch(e){$(errorId).textContent='Die Datei konnte nicht gelesen werden.'}}
function swiftFields(raw){const result=[];const pattern=/^:(\d{2}[A-Z]?):(.*?)(?=^:\d{2}[A-Z]?:|$)/gms;for(const match of String(raw||'').matchAll(pattern))result.push({code:match[1],value:match[2].trim()});return result}
function ensureCorrectionUi(){if($('#correctionBox'))return;const box=document.createElement('section');box.id='correctionBox';box.className='correction-box';box.innerHTML=`<h3>Angaben ergänzen oder verschieben</h3><p>Werte aus einem anderen Standardfeld oder aus der ursprünglichen SWIFT-Nachricht übernehmen.</p><div class="move-grid"><label>Quelle<select id="moveSource"></select></label><label>Ziel<select id="moveTarget"><option value="applicant">Applicant</option><option value="beneficiary">Beneficiary</option><option value="issuingBank">Issuing Bank</option><option value="advisingBank">Advising Bank</option><option value="expiryPlace">Ablaufort</option></select></label><button type="button" id="copyField" class="secondary">Übernehmen</button><button type="button" id="moveField">Verschieben</button></div><small>Übernehmen lässt die Quelle bestehen. Verschieben leert zusätzlich ein Standardfeld. Die Original-SWIFT-Nachricht bleibt unverändert.</small><label class="block-label">Erforderliche Dokumente – eine Angabe pro Zeile<textarea id="requiredDocumentsEdit" class="compact-textarea"></textarea></label><div class="sectionhead compact-head"><div><h3>Weitere Angaben</h3><p>Frei benennbare Informationen ohne passendes Standardfeld.</p></div><button type="button" id="addAdditionalField" class="secondary">+ Angabe</button></div><div id="additionalFieldsEdit" class="additional-fields"></div>`;$('#editForm').insertBefore(box,$('#editError'));$('#addAdditionalField').onclick=()=>addAdditionalRow('','');$('#copyField').onclick=()=>transferField(false);$('#moveField').onclick=()=>transferField(true)}
function addAdditionalRow(name,value){const row=document.createElement('div');row.className='additional-row';row.innerHTML=`<input class="additional-name" maxlength="255" placeholder="Bezeichnung" value="${esc(name)}"><textarea class="additional-value" maxlength="4000" placeholder="Angabe">${esc(value)}</textarea><button type="button" class="danger">×</button>`;row.querySelector('button').onclick=()=>row.remove();$('#additionalFieldsEdit').append(row)}
function transferField(clearSource){const form=$('#editForm'),source=$('#moveSource').value,target=$('#moveTarget').value;if(!source||!target)return;let value='';if(source.startsWith('standard:'))value=form.elements[source.substring(9)].value;else value=swiftFields(activeLc.rawMessage).find(x=>x.code===source.substring(6))?.value||'';form.elements[target].value=value;if(clearSource&&source.startsWith('standard:')&&source.substring(9)!==target)form.elements[source.substring(9)].value=''}
function openEdit(){if(!activeLc)return;ensureCorrectionUi();const form=$('#editForm'),known=assignableUsers.some(user=>user.username===activeLc.assignedTo);$('#assignedToSelect').innerHTML='<option value="">Nicht zugewiesen</option>'+(!known&&activeLc.assignedTo?`<option value="${esc(activeLc.assignedTo)}">${esc(activeLc.assignedTo)} (nicht aktiv)</option>`:'')+assignableUsers.map(user=>`<option value="${esc(user.username)}">${esc(user.displayName)} (${esc(user.username)})</option>`).join('');for(const key of ['reference','applicant','beneficiary','issuingBank','advisingBank','amount','currency','issueDate','expiryDate','expiryPlace','latestShipmentDate','assignedTo','followUpDate','status'])form.elements[key].value=activeLc[key]??'';const labels={applicant:'Applicant',beneficiary:'Beneficiary',issuingBank:'Issuing Bank',advisingBank:'Advising Bank',expiryPlace:'Ablaufort'};const standard=Object.entries(labels).filter(([key])=>form.elements[key].value).map(([key,label])=>`<option value="standard:${key}">${label}: ${esc(form.elements[key].value).slice(0,80)}</option>`);const swift=swiftFields(activeLc.rawMessage).map(x=>`<option value="swift:${x.code}">SWIFT :${x.code}: ${esc(x.value).slice(0,80)}</option>`);$('#moveSource').innerHTML='<option value="">Quelle auswählen …</option>'+standard.join('')+swift.join('');$('#requiredDocumentsEdit').value=(activeLc.requiredDocuments||[]).join('\n');$('#additionalFieldsEdit').innerHTML='';Object.entries(activeLc.additionalFields||{}).forEach(([name,value])=>addAdditionalRow(name,value));$('#editError').textContent='';$('#editDialog').showModal()}
let swiftItems=[];
function resetPreview(clearItems=false){if(clearItems)swiftItems=[];$('#preview').classList.add('hidden');$('#preview').innerHTML='';$('#submitImport').disabled=true;$('#error').textContent=''}
async function acceptSwiftFiles(files){const selected=[...files];if(!selected.length)return;resetPreview(true);for(const file of selected){const pdf=file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf'),limit=pdf?10485760:1048576;if(file.size>limit){swiftItems.push({filename:file.name,rawMessage:'',preview:{valid:false,messageType:'–',reference:null,errors:[`Datei ist größer als ${pdf?'10':'1'} MB.`],warnings:[],rawFields:[]}});continue}try{if(pdf){const body=new FormData();body.append('file',file);const result=await json('/api/imports/file-preview',{method:'POST',body});swiftItems.push({...result.request,preview:result.preview,extractionStatus:result.extractionStatus})}else swiftItems.push({filename:file.name,rawMessage:await file.text(),preview:null})}catch(e){swiftItems.push({filename:file.name,rawMessage:'',preview:{valid:false,messageType:'–',reference:null,errors:[e.message||'Datei konnte nicht gelesen werden.'],warnings:[],rawFields:[]}})}}$('#swiftFileName').textContent=`${selected.length} Datei${selected.length===1?'':'en'} ausgewählt · ${fileSize(selected.reduce((n,f)=>n+f.size,0))}`;await checkImport()}
function previewRow(item){const p=item.preview||{},state=p.valid?'ready':'invalid';const notes=[...(p.errors||[]),...(p.warnings||[])],unusual=(p.rawFields||[]).filter(f=>f.unusual).length;const fields=(p.rawFields||[]).map(f=>`<div class="swift-field ${f.unusual?'unusual':''}"><b>:${esc(f.code)}:</b><span>${esc(f.label)}</span><pre>${esc(f.value)}</pre><div class="field-suggestion"><span class="confidence ${String(f.confidence).toLowerCase()}">${f.confidence==='HIGH'?'Sicher':'Prüfen'}</span><b>→ ${esc(f.targetLabel)}</b><small>${esc(f.reason)}</small>${f.notice?`<strong class="placement-warning">⚠ ${esc(f.notice)}</strong>`:''}</div></div>`).join('');return `<div class="batch-row ${state}"><span class="batch-icon">${p.valid?'✓':'×'}</span><div><b>${esc(item.filename)}</b><small>${esc(p.messageType||'Nicht erkannt')} · ${esc(p.reference||'ohne Referenz')}</small>${notes.length?`<small class="batch-message">${notes.map(esc).join(' · ')}</small>`:''}${unusual?`<small class="placement-summary">⚠ ${unusual} ungewöhnliche ${unusual===1?'Zuordnung':'Zuordnungen'} prüfen</small>`:''}<details class="swift-fields"><summary>${(p.rawFields||[]).length} SWIFT-Felder und Zielvorschläge anzeigen</summary><div>${fields||'<small>Keine SWIFT-Felder erkannt.</small>'}</div></details></div><span class="import-status ${p.valid?'success':'rejected'}">${p.valid?'Bereit':'Abgelehnt'}</span></div>`}
async function checkImport(){const manual=$('#raw').value.trim();if(!swiftItems.length&&manual)swiftItems=[{filename:'Manuelle Eingabe',rawMessage:manual,preview:null}];if(!swiftItems.length){$('#error').textContent='Bitte mindestens eine SWIFT- oder PDF-Datei auswählen oder eine Nachricht einfügen.';return}$('#error').textContent='';$('#preview').innerHTML='<h3>Dateien werden geprüft …</h3>';$('#preview').classList.remove('hidden');await Promise.all(swiftItems.map(async item=>{if(item.preview)return;try{item.preview=await json('/api/imports/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(item)})}catch(e){item.preview={valid:false,messageType:'–',reference:null,errors:[e.message],warnings:[],rawFields:[]}}}));const valid=swiftItems.filter(x=>x.preview?.valid).length;$('#preview').innerHTML=`<h3>${valid} von ${swiftItems.length} Dateien importierbar</h3><div class="batch-list">${swiftItems.map(previewRow).join('')}</div>`;$('#submitImport').disabled=valid===0;$('#submitImport').textContent=`${valid} gültige importieren`}
$('#swiftFile').accept='.txt,.swift,.fin,.pdf,text/plain,application/pdf';$('#search').oninput=render;$('#lcTrafficFilter').onchange=render;$('#lcOwnerFilter').onchange=render;$('#lcSort').onchange=render;$('#importBtn').onclick=()=>{$('#swiftFileName').textContent='TXT, SWIFT, FIN oder PDF · PDF maximal 10 MB';$('#swiftFile').value='';$('#raw').value='';$('#submitImport').textContent='Gültige importieren';resetPreview(true);$('#importDialog').showModal()};
$('#raw').oninput=()=>resetPreview(true);$('#checkImport').onclick=checkImport;$('#swiftFile').onchange=()=>acceptSwiftFiles($('#swiftFile').files);
for(const event of ['dragenter','dragover'])$('#swiftDrop').addEventListener(event,e=>{e.preventDefault();$('#swiftDrop').classList.add('dragover')});for(const event of ['dragleave','drop'])$('#swiftDrop').addEventListener(event,e=>{e.preventDefault();$('#swiftDrop').classList.remove('dragover')});$('#swiftDrop').addEventListener('drop',e=>acceptSwiftFiles(e.dataTransfer.files));
$('#submitImport').onclick=async()=>{const valid=swiftItems.filter(x=>x.preview?.valid);$('#submitImport').disabled=true;const results=[];for(const item of valid){try{await json('/api/imports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(item)});results.push({...item,success:true})}catch(e){results.push({...item,success:false,error:e.message})}}const success=results.filter(x=>x.success).length;$('#preview').innerHTML=`<h3>Import abgeschlossen: ${success} erfolgreich, ${results.length-success} fehlgeschlagen</h3><div class="batch-list">${results.map(x=>`<div class="batch-row ${x.success?'ready':'invalid'}"><span class="batch-icon">${x.success?'✓':'×'}</span><div><b>${esc(x.filename)}</b><small>${x.success?'Import erfolgreich':esc(x.error)}</small></div></div>`).join('')}</div>`;$('#submitImport').textContent='Import abgeschlossen';await load()};
$('#closeEdit').onclick=$('#cancelEdit').onclick=()=>$('#editDialog').close();
$('#editForm').onsubmit=async event=>{event.preventDefault();if(!activeLc)return;const form=new FormData(event.target),payload=Object.fromEntries(form.entries());payload.amount=payload.amount===''?null:Number(payload.amount);for(const key of ['issueDate','expiryDate','latestShipmentDate','followUpDate'])payload[key]=payload[key]||null;payload.requiredDocuments=$('#requiredDocumentsEdit').value.split('\n').map(x=>x.trim()).filter(Boolean);payload.additionalFields={};document.querySelectorAll('.additional-row').forEach(row=>{const name=row.querySelector('.additional-name').value.trim(),value=row.querySelector('.additional-value').value.trim();if(name&&value)payload.additionalFields[name]=value});$('#editError').textContent='';try{await json(`/api/lcs/${activeLc.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});$('#editDialog').close();await load();await show(activeLc.id)}catch(e){$('#editError').textContent='Speichern fehlgeschlagen: '+e.message}};
$('#deleteLc').onclick=async()=>{if(!activeLc||!confirm(`Akkreditiv ${activeLc.reference} mit allen Dokumenten wirklich löschen?`))return;$('#editError').textContent='';try{await json(`/api/lcs/${activeLc.id}`,{method:'DELETE'});$('#editDialog').close();$('#detail').classList.add('hidden');activeLc=null;await load()}catch(e){$('#editError').textContent='Löschen fehlgeschlagen: '+e.message}};
$('#uploadForm').onsubmit=async event=>{event.preventDefault();if(!activeLc)return;$('#uploadError').textContent='';const form=new FormData(event.target),file=form.get('file'),archive=file?.name?.toLowerCase().endsWith('.zip');try{await json(`/api/lcs/${activeLc.id}/documents${archive?'/archive':''}`,{method:'POST',body:form});$('#uploadDialog').close();await show(activeLc.id)}catch(e){$('#uploadError').textContent='Upload fehlgeschlagen: '+e.message}};
function resetUserForm(){const f=$('#userForm');f.reset();f.elements.id.value='';f.elements.active.checked=true;f.elements.password.required=true;$('#userError').textContent=''}
function renderUsers(){const role=x=>({ADMIN:'Administrator',EDITOR:'Sachbearbeiter',VIEWER:'Leser',USER:'Sachbearbeiter'})[x]||x;$('#userList').innerHTML=users.map(u=>`<div class="user-row" data-id="${u.id}"><div><b>${esc(u.displayName)}</b><small>${esc(u.username)} · ${role(u.role)}</small></div><span class="import-status ${u.active?'success':'rejected'}">${u.active?'Aktiv':'Gesperrt'}</span><button type="button" class="danger delete-user" data-id="${u.id}">Löschen</button></div>`).join('');document.querySelectorAll('.user-row').forEach(row=>row.onclick=e=>{if(e.target.classList.contains('delete-user'))return;const u=users.find(x=>x.id===row.dataset.id),f=$('#userForm');for(const k of ['id','username','displayName'])f.elements[k].value=u[k];f.elements.role.value=u.role==='USER'?'EDITOR':u.role;f.elements.active.checked=u.active;f.elements.password.value='';f.elements.password.required=false;$('#userError').textContent=''});document.querySelectorAll('.delete-user').forEach(button=>button.onclick=async()=>{const u=users.find(x=>x.id===button.dataset.id);if(!confirm(`Benutzer ${u.username} wirklich löschen?`))return;try{await json(`/api/users/${u.id}`,{method:'DELETE'});await loadUsers()}catch(e){$('#userError').textContent=e.message}})}
async function loadUsers(){users=await json('/api/users');renderUsers()}
$('#usersBtn').onclick=async()=>{resetUserForm();$('#usersDialog').showModal();try{await loadUsers()}catch(e){$('#userError').textContent=e.message}};$('#closeUsers').onclick=()=>$('#usersDialog').close();$('#newUser').onclick=resetUserForm;
const auditLabels={LOGIN:'Anmeldung',LOGOUT:'Abmeldung',PASSWORD_CHANGED:'Passwort geändert',USER_CREATED:'Benutzer angelegt',USER_UPDATED:'Benutzer geändert',USER_DELETED:'Benutzer gelöscht',LC_IMPORTED:'Akkreditiv importiert',LC_UPDATED:'Akkreditiv geändert',LC_DELETED:'Akkreditiv gelöscht',LC_ASSIGNED:'Akte zugewiesen',LC_NOTE_ADDED:'Aktennotiz',LC_FOLLOW_UP_COMPLETED:'Wiedervorlage erledigt',LC_TASK_CREATED:'Aufgabe angelegt',LC_TASK_COMPLETED:'Aufgabe erledigt',LC_TASK_REOPENED:'Aufgabe wieder geöffnet',LC_TASK_DELETED:'Aufgabe gelöscht',CALENDAR_EXPORTED:'Kalender exportiert',DOCUMENT_REQUIREMENT_MAPPED:'Dokumentenanforderung zugeordnet',SWIFT_IMPORTED:'SWIFT importiert',MT707_IMPORTED:'MT707-Amendment importiert',DOCUMENT_UPLOADED:'Dokument hochgeladen',DOCUMENT_ARCHIVE_UPLOADED:'ZIP-Akte hochgeladen',DOCUMENT_GENERATED:'Dokument erstellt',DOCUMENT_UPDATED:'Dokumentdaten geändert',DOCUMENT_DELETED:'Dokument gelöscht',DOCUMENT_CHECK_DECIDED:'Prüfentscheidung gespeichert',DOCUMENT_CHECK_DECISIONS_RESET:'Prüfentscheidungen zurückgesetzt',DOCUMENT_CHECK_REPORT_CREATED:'Prüfbericht erstellt',LC_DOSSIER_EXPORTED:'LC-Akte exportiert',TRAINING_STARTED:'Training begonnen',TRAINING_PROGRESS_SAVED:'Trainingsstand gelernt',TRAINING_CONFIRMED:'Training abgeschlossen',TRAINING_RULE_ACTIVATED:'Lernregel aktiviert',TRAINING_RULE_DEACTIVATED:'Lernregel deaktiviert',TRAINING_DELETED:'Trainingsvorlage gelöscht',TRAINING_TEMPLATES_DELETED:'Trainingsvorlagen gesammelt gelöscht'};
let auditEvents=[];function auditArea(event){const action=event.action||'',type=event.entityType||'';if(action.startsWith('TRAINING'))return'TRAINING';if(action.startsWith('DOCUMENT')||type==='DOCUMENT')return'DOCUMENT';if(action.startsWith('USER')||action==='PASSWORD_CHANGED')return'USER';if(type==='SESSION'||['LOGIN','LOGOUT'].includes(action))return'SESSION';return'LC'}
function filterAudit(){const query=$('#auditSearch').value.trim().toLowerCase(),area=$('#auditArea').value,result=$('#auditResult').value;renderAudit(auditEvents.filter(event=>(!query||[event.username,event.action,auditLabels[event.action],event.details,event.entityId].join(' ').toLowerCase().includes(query))&&(!area||auditArea(event)===area)&&(!result||(result==='success')===event.successful)))}
function renderAudit(events){$('#auditCount').textContent=`${events.length} von ${auditEvents.length} Ereignissen`;$('#auditList').innerHTML=events.length?events.map(e=>`<div class="audit-row"><span class="audit-state ${e.successful?'success':'rejected'}">${e.successful?'✓':'×'}</span><div><b>${esc(auditLabels[e.action]||e.action)}</b><small><span class="audit-area">${esc(auditArea(e))}</span> ${esc(e.details||e.entityType||'–')}</small></div><div><b>${esc(e.username)}</b><small>${e.ipAddress?'IP '+esc(e.ipAddress):''}</small></div><small>${new Intl.DateTimeFormat('de-DE',{dateStyle:'short',timeStyle:'medium'}).format(new Date(e.occurredAt))}</small></div>`).join(''):'<div class="empty compact">Keine passenden Aktionen gefunden.</div>'}
$('#auditBtn').onclick=async()=>{$('#auditDialog').showModal();$('#auditList').innerHTML='<div class="empty compact">Protokoll wird geladen …</div>';try{auditEvents=await json('/api/audit');filterAudit()}catch(e){$('#auditList').innerHTML=`<div class="error">${esc(e.message)}</div>`}};for(const id of ['#auditSearch','#auditArea','#auditResult'])$(id).addEventListener(id==='#auditSearch'?'input':'change',filterAudit);$('#closeAudit').onclick=()=>$('#auditDialog').close();
$('#userForm').onsubmit=async event=>{event.preventDefault();const f=event.target,values=Object.fromEntries(new FormData(f).entries()),id=values.id;values.active=f.elements.active.checked;delete values.id;if(!values.password)values.password=null;try{await json(id?`/api/users/${id}`:'/api/users',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});resetUserForm();await loadUsers()}catch(e){$('#userError').textContent=e.message}};
