$('#passwordForm').onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.target).entries());$('#passwordError').textContent='';$('#passwordSuccess').textContent='';if(values.newPassword!==values.confirmation){$('#passwordError').textContent='Die neuen Passwörter stimmen nicht überein.';return}try{await json('/api/auth/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({currentPassword:values.currentPassword,newPassword:values.newPassword})});event.target.reset();$('#passwordSuccess').textContent='Passwort wurde erfolgreich geändert.'}catch(e){$('#passwordError').textContent=e.message}};
let trainingItem=null;
function ensureTrainingUi(){if($('#trainingBtn'))return;const button=document.createElement('button');button.id='trainingBtn';button.className='secondary';button.textContent='Training & Erkennung';button.onclick=openTraining;document.querySelector('.header-actions').insertBefore(button,$('#auditBtn'));const dialog=document.createElement('dialog');dialog.id='trainingDialog';dialog.className='wide-dialog';dialog.innerHTML=`<div class="dialoghead"><div><h2>SWIFT Training & Dokumentenerkennung</h2><p>MT700, MT707 und MT760 automatisch erkennen und jedes Feld fachlich bestätigen.</p></div><button type="button" id="closeTraining" class="ghost">×</button></div><div class="training-body"><label id="trainingDrop" class="training-drop"><span class="file-picker-icon">↑</span><span><b>SWIFT-PDF hier ablegen oder auswählen</b><small>MT700 · MT707 · MT760 · digitale PDFs und Scans · maximal 10 MB</small></span><input id="trainingFile" type="file" accept=".pdf,application/pdf"></label><div id="trainingStatus"></div><div id="trainingFields" class="training-fields"></div><div id="trainingError" class="error"></div></div><div class="actions"><button type="button" id="cancelTraining" class="secondary">Schließen</button><button type="button" id="confirmTraining" disabled>Felder bestätigen</button></div>`;document.body.append(dialog);$('#closeTraining').onclick=$('#cancelTraining').onclick=()=>dialog.close();$('#trainingFile').onchange=()=>processTrainingFile($('#trainingFile').files[0]);for(const name of ['dragenter','dragover','dragleave','drop'])$('#trainingDrop').addEventListener(name,event=>{event.preventDefault();if(name==='drop')processTrainingFile(event.dataTransfer.files[0])});$('#confirmTraining').onclick=confirmTraining}
function openTraining(){trainingItem=null;$('#trainingFile').value='';$('#trainingFields').innerHTML='';$('#trainingStatus').innerHTML='';$('#trainingError').textContent='';$('#confirmTraining').disabled=true;$('#confirmTraining').classList.remove('hidden');$('#trainingDrop').classList.remove('hidden');if(!$('#trainingHistory'))$('#trainingDrop').insertAdjacentHTML('afterend','<div id="trainingQuality" class="training-quality"></div><div id="learningHistory" class="learning-history"></div><div id="trainingHistory" class="training-history"></div>');loadTrainingHistory();loadLearningRules();$('#trainingDialog').showModal()}
async function loadTrainingHistory(){try{const rows=await json('/api/training');$('#trainingHistory').innerHTML=rows.length?`<details><summary>Trainingshistorie (${rows.length})</summary><div class="training-bulk-actions"><button type="button" class="danger" id="deleteSelectedTraining">Ausgewählte Vorlagen löschen</button><small>Die Lerninhalte bleiben erhalten.</small></div>${rows.slice(0,100).map(x=>`<div class="training-history-row selectable"><input type="checkbox" class="training-select" value="${x.id}" aria-label="${esc(x.filename)} auswählen"><div><b>${esc(x.filename)}</b><small>${esc(x.username)} · ${new Intl.DateTimeFormat('de-DE',{dateStyle:'short',timeStyle:'short'}).format(new Date(x.createdAt))}</small></div><span>${esc(x.messageType||'Unbekannt')} · ${x.status==='CONFIRMED'?'Bestätigt':'Entwurf'}</span><div class="training-links"><button type="button" class="secondary" onclick="openTrainingSession('${x.id}')">Öffnen</button><a href="/api/training/${x.id}/document" target="_blank">PDF</a>${x.status==='CONFIRMED'?`<a href="/api/training/${x.id}/export.json">JSON</a><a href="/api/training/${x.id}/export.xml">XML</a>`:''}<button type="button" class="danger training-delete" data-training-delete="${x.id}" data-training-name="${esc(x.filename)}">Löschen</button></div></div>`).join('')}</details>`:'<small>Noch keine Trainingsdaten gespeichert.</small>';document.querySelectorAll('[data-training-delete]').forEach(button=>button.onclick=()=>deleteTraining(button));$('#deleteSelectedTraining')?.addEventListener('click',deleteSelectedTraining);await loadTrainingQuality()}catch(e){$('#trainingHistory').innerHTML=''}}
async function deleteTraining(button){if(!confirm(`Trainingsvorlage „${button.dataset.trainingName}“ ausblenden? Die Lerninhalte bleiben erhalten.`))return;button.disabled=true;try{await json(`/api/training/${button.dataset.trainingDelete}`,{method:'DELETE'});if(trainingItem?.sessionId===button.dataset.trainingDelete){trainingItem=null;$('#trainingDialog').close()}await Promise.all([loadTrainingHistory(),loadDashboardDrafts()])}catch(e){$('#trainingError').textContent='Löschen fehlgeschlagen: '+e.message;button.disabled=false}}
async function deleteSelectedTraining(){const ids=[...document.querySelectorAll('.training-select:checked')].map(x=>x.value);if(!ids.length){alert('Bitte zuerst Trainingsvorlagen auswählen.');return}if(!confirm(`${ids.length} Trainingsvorlage(n) ausblenden? Die Lerninhalte bleiben erhalten.`))return;try{await json('/api/training/templates',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify(ids)});await Promise.all([loadTrainingHistory(),loadDashboardDrafts()])}catch(e){$('#trainingError').textContent='Löschen fehlgeschlagen: '+e.message}}
async function openTrainingSession(id){try{const item=await json(`/api/training/${id}`);trainingItem={sessionId:item.id,extractionStatus:item.extractionStatus,preview:{messageType:item.messageType,rawFields:item.fields||[],valid:false,errors:[]},reviews:(item.fields||[]).map(x=>x.review||'correct')};$('#trainingDrop').classList.add('hidden');renderTraining();document.querySelectorAll('.training-field textarea').forEach(x=>x.readOnly=true);document.querySelectorAll('.review-actions').forEach(x=>x.classList.add('hidden'));$('#confirmTraining').classList.add('hidden');$('#trainingReviewProgress').textContent=`${item.status==='CONFIRMED'?'Bestätigter Datensatz':'Entwurf'} · ${esc(item.filename)}`}catch(e){$('#trainingError').textContent=e.message}}
async function loadTrainingQuality(){try{const rows=await json('/api/training/quality');$('#trainingQuality').innerHTML=rows.length?`<details><summary>OCR-Qualität nach Profil und Feld</summary><div class="quality-profiles">${rows.map(p=>`<section><h4>${esc(p.messageType)} <span>${p.accuracyPercent}% unverändert erkannt</span></h4><small>${p.sessions} bestätigte Dokumente · ${p.fields} geprüfte Felder · ${p.corrected} korrigiert</small><div class="quality-fields">${p.fieldQuality.map(f=>`<span>:${esc(f.code)}: <b>${f.accuracyPercent}%</b><small>${f.confirmed}× geprüft</small></span>`).join('')}</div></section>`).join('')}</div></details>`:'<small>Noch nicht genügend bestätigte Daten für die Qualitätsanzeige.</small>'}catch(e){$('#trainingQuality').innerHTML=''}}
async function loadLearningRules(){try{const rules=await json('/api/training/learning-rules');$('#learningHistory').innerHTML=rules.length?`<details><summary>Lernhistorie (${rules.length} Regeln)</summary><div class="learning-rules">${rules.map(rule=>`<section class="learning-rule ${rule.active?'':'inactive'}"><div><b>${esc(rule.messageType)} · ${esc(rule.kind)}</b><small>:${esc(rule.sourceCode)}:${rule.sourceValue?` „${esc(rule.sourceValue)}“`:''} → ${rule.rejected?'nicht verwenden':`:${esc(rule.targetCode)}:${rule.targetValue?` „${esc(rule.targetValue)}“`:''}`}</small><small>${rule.examples}× gelernt · ${rule.documents.map(esc).join(', ')}</small></div><button type="button" class="secondary learning-toggle" data-id="${rule.id}" data-active="${rule.active}">${rule.active?'Deaktivieren':'Aktivieren'}</button></section>`).join('')}</div></details>`:'<small>Noch keine dauerhaften Lernregeln vorhanden.</small>';document.querySelectorAll('.learning-toggle').forEach(button=>button.onclick=()=>toggleLearningRule(button))}catch(e){$('#learningHistory').innerHTML='<small>Lernhistorie konnte nicht geladen werden.</small>'}}
async function toggleLearningRule(button){button.disabled=true;try{await json(`/api/training/learning-rules/${button.dataset.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:button.dataset.active!=='true'})});await loadLearningRules()}catch(e){$('#trainingError').textContent=e.message;button.disabled=false}}
async function processTrainingFile(file){if(!file)return;$('#trainingError').textContent='';$('#trainingStatus').innerHTML='<div class="empty compact">PDF wird gelesen, gespeichert und analysiert …</div>';$('#trainingFields').innerHTML='';$('#confirmTraining').disabled=true;try{const body=new FormData();body.append('file',file);const result=await json('/api/training/preview',{method:'POST',body});trainingItem={...result.request,sessionId:result.sessionId,preview:result.preview,extractionStatus:result.extractionStatus,reviews:(result.preview.rawFields||[]).map(()=>null)};renderTraining();loadTrainingHistory()}catch(e){$('#trainingStatus').innerHTML='';$('#trainingError').textContent=e.message}}
function updateTrainingReview(){const total=trainingItem.reviews.length,done=trainingItem.reviews.filter(Boolean).length;$('#trainingReviewProgress').textContent=`${done} von ${total} Feldern fachlich bestätigt`;$('#confirmTraining').disabled=total===0}
function setTrainingReview(index,status){trainingItem.reviews[index]=status;const row=document.querySelector(`.training-field[data-index="${index}"]`);row.classList.remove('review-correct','review-corrected','review-reassigned','review-invalid');row.classList.add(`review-${status}`);row.querySelectorAll('.review-actions button').forEach(button=>button.classList.toggle('selected',button.dataset.review===status));if(status==='corrected'||status==='reassigned'||status==='invalid')$('#trainingError').textContent='';updateTrainingReview()}
const swiftCatalog={MT700:['20','27','31C','31D','32B','40A','40E','41A','41D','42A','42C','42M','42P','43P','43T','44A','44B','44C','44E','44F','45A','46A','47A','48','49','50','52A','57A','59','71D','72Z','78'],MT707:['20','21','23','26E','27','30','31E','32B','33B','44C','45B','46B','47B','52A','57A','59','72'],MT760:['15A','15B','20','21','22A','22D','23','23B','23H','24E','24G','27','30','31C','31D','32B','40C','45C','45L','50','52A','59','77C','77U']};
function swiftFieldOptions(type,current){const codes=[...new Set([current,...(swiftCatalog[type]||swiftCatalog.MT700)])];return codes.map(code=>`<option value="${esc(code)}" ${code===current?'selected':''}>:${esc(code)}:</option>`).join('')}
function reassignTrainingField(index){const row=document.querySelector(`.training-field[data-index="${index}"]`),select=row.querySelector('.swift-code-select'),field=trainingItem.preview.rawFields[index];row.querySelector('.training-field-head b').textContent=`SWIFT-Feld :${select.value}:`;row.querySelector('.field-reassignment small').textContent=select.value===field.code?'Ursprüngliche Zuordnung':'Ursprünglich als :'+field.code+': erkannt';setTrainingReview(index,select.value===field.code?'correct':'reassigned')}
async function loadTrainingSnippets(){for(const img of document.querySelectorAll('.snippet-frame img')){const frame=img.parentElement;try{const response=await fetch(img.dataset.src,{credentials:'same-origin'});if(!response.ok)throw new Error(`HTTP ${response.status}`);const blob=await response.blob();if(!blob.size)throw new Error('Leere Bildantwort');const url=URL.createObjectURL(blob);img.onload=()=>{frame.classList.add('loaded');URL.revokeObjectURL(url)};img.onerror=()=>{frame.classList.add('failed');frame.querySelector('span').textContent='PDF-Ausschnitt ist kein gültiges Bild';URL.revokeObjectURL(url)};img.src=url}catch(error){frame.classList.add('failed');frame.querySelector('span').textContent=`PDF-Ausschnitt konnte nicht geladen werden (${error.message})`}}}
function openSnippetZoom(img){let dialog=$('#snippetZoomDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='snippetZoomDialog';dialog.className='snippet-zoom-dialog';dialog.innerHTML='<div class="dialoghead"><div><h2>PDF-Ausschnitt vergrößert</h2><p>Zur Detailprüfung des erkannten SWIFT-Feldes.</p></div><button type="button" class="ghost">×</button></div><div class="snippet-zoom-content"><img alt="Vergrößerter PDF-Ausschnitt"></div><div class="actions"><button type="button" class="secondary">Schließen</button></div>';document.body.append(dialog);dialog.querySelectorAll('button').forEach(button=>button.onclick=()=>dialog.close())}dialog.querySelector('img').src=img.src;dialog.showModal()}
function openOriginalPdf(){if(!trainingItem?.sessionId)return;const url=`/api/training/${trainingItem.sessionId}/document`;let dialog=$('#originalPdfDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='originalPdfDialog';dialog.className='original-pdf-dialog';dialog.innerHTML='<div class="dialoghead"><div><h2>Original-PDF</h2><p>Vollständiges Dokument zur fachlichen Prüfung.</p></div><button type="button" class="ghost close-original">×</button></div><iframe title="Vollständiges Original-PDF"></iframe><div class="actions"><a class="button-link" target="_blank" rel="noopener">In eigenem Tab öffnen</a><button type="button" class="secondary close-original">Schließen</button></div>';document.body.append(dialog);dialog.querySelectorAll('.close-original').forEach(button=>button.onclick=()=>dialog.close())}dialog.querySelector('iframe').src=url;dialog.querySelector('a').href=url;dialog.showModal()}
function renderTraining(){const p=trainingItem.preview,fields=p.rawFields||[],unclear=fields.filter(x=>x.confidence!=='HIGH').length;$('#confirmTraining').textContent=p.messageType==='MT700'?'Bestätigen & LC anlegen':p.messageType==='MT707'?'Bestätigen & Amendment übernehmen':'Bestätigen & Trainingsdaten speichern';$('#trainingStatus').innerHTML=`<div class="training-summary"><b>${esc(p.messageType||'Format unbekannt')}</b><span>${fields.length} Felder</span><span>${unclear} automatisch unsicher</span><span>${trainingItem.extractionStatus==='OCR_EXTRACTED'?'OCR verwendet':'Textschicht erkannt'}</span><strong id="trainingReviewProgress"></strong></div><div id="trainingGate" class="training-gate"><span>Qualitätsprüfung wird vorbereitet …</span></div>`;$('#trainingFields').innerHTML=fields.map((f,index)=>`<div class="training-field ${f.unusual?'unusual':''}" data-index="${index}"><div class="training-field-head"><b>SWIFT-Feld :${esc(f.code)}:</b><span>${esc(f.label)}</span><label class="field-reassignment">Anderem SWIFT-Feld zuordnen<select class="swift-code-select">${swiftFieldOptions(p.messageType,f.code)}</select><small>Ursprüngliche Zuordnung</small></label></div><div class="pdf-context"><small>Original im PDF</small><div class="snippet-frame"><span>PDF-Ausschnitt wird vorbereitet …</span><img data-src="/api/training/${trainingItem.sessionId}/snippet/${index}?v=5" alt="PDF-Ausschnitt für Feld ${esc(f.code)}"><button type="button" class="snippet-zoom">⌕ Vergrößern</button></div></div><div class="training-value"><small>Erkannter Feldinhalt</small><textarea maxlength="12000">${esc(f.value)}</textarea><div class="review-actions"><button type="button" class="secondary" data-review="correct">✓ Richtig erkannt</button><button type="button" class="secondary" data-review="corrected">✎ Korrektur bestätigen</button><button type="button" class="reject-review" data-review="invalid">× Nicht verwendbar</button></div></div><div class="training-target"><small>Zuordnung im LC-Manager</small><span class="confidence ${String(f.confidence).toLowerCase()}">${f.confidence==='HIGH'?'Automatisch sicher':'Automatisch prüfen'}</span><b>${esc(f.targetLabel)}</b>${f.notice?`<small class="placement-warning">${esc(f.notice)}</small>`:''}</div></div>`).join('');loadTrainingSnippets();document.querySelectorAll('.training-field').forEach(row=>{const index=Number(row.dataset.index);row.querySelectorAll('.review-actions button').forEach(button=>button.onclick=()=>setTrainingReview(index,button.dataset.review));row.querySelector('.swift-code-select').onchange=()=>reassignTrainingField(index);row.querySelector('.snippet-zoom').onclick=()=>{const img=row.querySelector('.snippet-frame img');if(img.src)openSnippetZoom(img)};row.querySelector('.snippet-frame img').onclick=event=>openSnippetZoom(event.currentTarget);row.querySelector('textarea').oninput=()=>{trainingItem.reviews[index]=null;$('#trainingError').textContent='';row.classList.remove('review-correct','review-corrected','review-reassigned','review-invalid');row.querySelectorAll('.review-actions button').forEach(button=>button.classList.remove('selected'));updateTrainingReview()}});updateTrainingReview();$('#trainingError').textContent=p.errors?.join(' ')||''}
async function confirmTraining(){const open=trainingItem.reviews.map((status,index)=>status?null:trainingItem.preview.rawFields[index]?.code||String(index+1)).filter(Boolean);if(open.length){$('#trainingError').textContent=`Noch nicht fachlich bestätigt: ${open.map(code=>':'+code+':').join(', ')}. Bitte diese Felder bestätigen, neu zuordnen oder als nicht verwendbar markieren.`;const first=document.querySelector(`.training-field[data-index="${trainingItem.reviews.findIndex(status=>!status)}"]`);first?.scrollIntoView({behavior:'smooth',block:'center'});return}const fields=trainingItem.preview.rawFields.map((field,index)=>{const row=document.querySelector(`.training-field[data-index="${index}"]`);return {...field,originalCode:field.code,code:row.querySelector('.swift-code-select').value,value:row.querySelector('textarea').value.trim(),review:trainingItem.reviews[index]}});const raw=fields.filter(f=>f.review!=='invalid').map(f=>`:${f.code}:${f.value}`).join('\n');$('#confirmTraining').disabled=true;$('#trainingError').textContent='';try{await json(`/api/training/${trainingItem.sessionId}/confirm`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({correctedRawMessage:raw,reviewsJson:JSON.stringify(fields)})});$('#trainingDialog').close();await load()}catch(e){$('#trainingError').textContent=e.message;$('#confirmTraining').disabled=false}}
let tlsStatus=null;
async function loadTlsStatus(){const button=$('#tlsStatusBtn');try{tlsStatus=await json('/api/security/tls-status');button.className=`tls-status tls-${tlsStatus.status.toLowerCase()}`;button.querySelector('.tls-copy b').textContent=tlsStatus.label;button.querySelector('.tls-copy small').textContent=tlsStatus.message}catch(e){tlsStatus={status:'YELLOW',label:'Prüfung nicht möglich',message:'Der Verbindungsstatus konnte nicht geladen werden.',encrypted:location.protocol==='https:',scheme:location.protocol.replace(':',''),host:location.host,proxyIndicators:[],limitation:'Die Ampel konnte keine Serverprüfung durchführen.'};button.className='tls-status tls-yellow';button.querySelector('.tls-copy b').textContent=tlsStatus.label;button.querySelector('.tls-copy small').textContent=tlsStatus.message}}
function showTlsDetails(){if(!tlsStatus)return;const color={GREEN:'Grün',YELLOW:'Gelb',RED:'Rot'}[tlsStatus.status]||tlsStatus.status;$('#tlsDetails').innerHTML=`<div class="tls-result tls-${String(tlsStatus.status).toLowerCase()}"><span class="traffic-light large"><i class="red"></i><i class="yellow"></i><i class="green"></i></span><div><h3>${esc(color)} – ${esc(tlsStatus.label)}</h3><p>${esc(tlsStatus.message)}</p></div></div><dl><dt>Verbindung</dt><dd>${tlsStatus.encrypted?'HTTPS / verschlüsselt':'nicht als HTTPS erkannt'}</dd><dt>Adresse</dt><dd>${esc(tlsStatus.host||location.host)}</dd><dt>Sichtbare Indikatoren</dt><dd>${tlsStatus.proxyIndicators?.length?tlsStatus.proxyIndicators.map(esc).join(', '):'Keine typischen Proxy-/Inspection-Header erkannt'}</dd></dl><p class="tls-limitation"><b>Wichtig:</b> ${esc(tlsStatus.limitation)}</p>`;$('#tlsDialog').showModal()}
$('#tlsStatusBtn').onclick=showTlsDetails;$('#closeTls').onclick=$('#closeTlsAction').onclick=()=>$('#tlsDialog').close();
const renderTrainingFields=renderTraining;renderTraining=function(){renderTrainingFields();const button=document.createElement('button');button.type='button';button.id='showOriginalPdf';button.className='secondary';button.textContent='▣ Original-PDF anzeigen';button.onclick=openOriginalPdf;$('#trainingReviewProgress').after(button)};
let trainingSaveTimer=null,trainingQualityTimer=null;
function trainingDraftPayload(){const fields=trainingItem.preview.rawFields.map((field,index)=>{const row=document.querySelector(`.training-field[data-index="${index}"]`);return {...field,originalCode:field.originalCode||field.code,code:row?.querySelector('.swift-code-select')?.value||field.code,value:row?.querySelector('textarea')?.value.trim()??field.value,review:trainingItem.reviews[index]}});return {correctedRawMessage:fields.filter(field=>field.review!=='invalid').map(field=>`:${field.code}:${field.value}`).join('\n'),reviewsJson:JSON.stringify(fields)}}
function scheduleTrainingSave(){if(!trainingItem?.sessionId||trainingItem.status==='CONFIRMED')return;clearTimeout(trainingSaveTimer);clearTimeout(trainingQualityTimer);let state=$('#trainingAutosave');if(!state){state=document.createElement('small');state.id='trainingAutosave';state.className='training-autosave';$('#trainingReviewProgress').after(state)}state.textContent='Änderung wird gespeichert …';trainingSaveTimer=setTimeout(saveTrainingDraft,500);trainingQualityTimer=setTimeout(validateTrainingQuality,750)}
async function validateTrainingQuality(){if(!trainingItem?.sessionId||trainingItem.status==='CONFIRMED'||!$('#trainingGate'))return;try{const result=await json(`/api/training/${trainingItem.sessionId}/validate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(trainingDraftPayload())}),labels={GREEN:'Grün – fachlich plausibel',YELLOW:'Gelb – Hinweise prüfen',RED:'Rot – Abschluss nicht möglich'},items=[...result.blockers,...result.warnings,...result.information];$('#trainingGate').className=`training-gate gate-${result.status.toLowerCase()}`;$('#trainingGate').innerHTML=`<span class="traffic-light tls-${result.status.toLowerCase()}"><i class="red"></i><i class="yellow"></i><i class="green"></i></span><div><b>${labels[result.status]}</b>${items.length?`<ul>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:'<small>Keine Auffälligkeiten gefunden.</small>'}</div>`}catch(e){$('#trainingGate').className='training-gate gate-yellow';$('#trainingGate').textContent='Qualitätsprüfung derzeit nicht möglich: '+e.message}}
async function saveTrainingDraft(){const state=$('#trainingAutosave');try{await json(`/api/training/${trainingItem.sessionId}/draft`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(trainingDraftPayload())});if(state)state.textContent='Zwischenstand gespeichert und gelernt';loadTrainingQuality()}catch(e){if(state)state.textContent='Zwischenspeichern fehlgeschlagen'}}
const reviewTrainingField=setTrainingReview;setTrainingReview=function(index,status){reviewTrainingField(index,status);scheduleTrainingSave()};
const renderTrainingAutosave=renderTraining;renderTraining=function(){trainingItem.preview.rawFields.forEach(field=>{if(field.originalValue==null)field.originalValue=field.value});renderTrainingAutosave();if(trainingItem.status!=='CONFIRMED'){document.querySelectorAll('.training-field textarea').forEach(textarea=>textarea.addEventListener('input',scheduleTrainingSave));validateTrainingQuality()}};
openTrainingSession=async function(id){try{const item=await json(`/api/training/${id}`),editable=item.status!=='CONFIRMED';trainingItem={sessionId:item.id,status:item.status,extractionStatus:item.extractionStatus,preview:{messageType:item.messageType,rawFields:item.fields||[],valid:editable,errors:[]},reviews:(item.fields||[]).map(field=>field.review||null)};$('#trainingDrop').classList.add('hidden');$('#confirmTraining').classList.toggle('hidden',!editable);renderTraining();if(!editable){document.querySelectorAll('.training-field textarea,.training-field select').forEach(control=>control.disabled=true);document.querySelectorAll('.review-actions').forEach(actions=>actions.classList.add('hidden'))}$('#trainingReviewProgress').textContent=`${editable?'Bearbeitbarer Entwurf':'Bestätigter Datensatz'} · ${esc(item.filename)}`}catch(e){$('#trainingError').textContent=e.message}};
const confirmTrainingImport=confirmTraining;confirmTraining=async function(){const existing=new Set(data.map(item=>item.id));await confirmTrainingImport();if(!$('#trainingDialog').open){$('#search').value='';render();const created=data.find(item=>!existing.has(item.id));if(created)await show(created.id);else $('#list').scrollIntoView({behavior:'smooth',block:'start'})}};
async function init(){currentUser=await json('/api/auth/me');csrfToken=currentUser.csrfToken;if(currentUser.role==='ADMIN'){ $('#usersBtn').classList.remove('hidden');$('#auditBtn').classList.remove('hidden');$('#appNavUsers').classList.remove('hidden');$('#appNavAudit').classList.remove('hidden');$('.admin-nav-label').classList.remove('hidden')}if(currentUser.role==='VIEWER')document.body.classList.add('read-only');[assignableUsers,openTasks]=await Promise.all([json('/api/users/assignable').catch(()=>[]),json('/api/tasks/open').catch(()=>[])]);await Promise.all([load(),loadTlsStatus()])}
function ensureDocumentCreationUi(){if($('#generateDocumentDialog'))return;const dialog=document.createElement('dialog');dialog.id='generateDocumentDialog';dialog.innerHTML=`<form id="generateDocumentForm"><div class="dialoghead"><div><h2 id="generateDocumentTitle">Dokument erstellen</h2><p>LC-Daten werden automatisch übernommen.</p></div><button type="button" class="ghost generate-close">×</button></div><input type="hidden" name="type"><div class="form-grid"><label>Dokumentnummer<input name="documentNumber" required maxlength="100"></label><label>Dokumentdatum<input name="documentDate" type="date" required></label><label class="wide">Warenbeschreibung<textarea name="description" class="compact-textarea" maxlength="4000"></textarea></label><label>Menge<input name="quantity" maxlength="100" placeholder="z. B. 100 Stück"></label><label>Packstücke<input name="packages" type="number" min="0"></label><label>Nettogewicht (kg)<input name="netWeight" type="number" min="0" step="0.001"></label><label>Bruttogewicht (kg)<input name="grossWeight" type="number" min="0" step="0.001"></label><label class="wide">Hinweise<textarea name="notes" class="compact-textarea" maxlength="4000"></textarea></label></div><div id="generateDocumentError" class="error"></div><div class="actions"><button type="button" class="secondary generate-close">Abbrechen</button><button type="submit">PDF erstellen und speichern</button></div></form>`;document.body.append(dialog);dialog.querySelectorAll('.generate-close').forEach(button=>button.onclick=()=>dialog.close());$('#generateDocumentForm').onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.target).entries());for(const key of ['packages','netWeight','grossWeight'])values[key]=values[key]===''?null:Number(values[key]);try{await json(`/api/lcs/${activeLc.id}/generated-documents`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});dialog.close();await show(activeLc.id)}catch(e){$('#generateDocumentError').textContent=e.message}}}
function openDocumentCreation(type){ensureDocumentCreationUi();const form=$('#generateDocumentForm');form.reset();form.elements.type.value=type;form.elements.documentDate.value=new Date().toISOString().slice(0,10);form.elements.documentNumber.value=(type==='COMMERCIAL_INVOICE'?'INV-':'PL-')+activeLc.reference;form.elements.description.value=Object.entries(activeLc.additionalFields||{}).find(([key])=>key.includes('45A'))?.[1]||swiftFields(activeLc.rawMessage).find(field=>field.code==='45A')?.value||'';$('#generateDocumentTitle').textContent=type==='COMMERCIAL_INVOICE'?'Handelsrechnung erstellen':'Packliste erstellen';$('#generateDocumentError').textContent='';$('#generateDocumentDialog').showModal()}
const showWithDocumentCreation=show;show=async function(id){await showWithDocumentCreation(id);const refresh=$('#refreshChecks');if(refresh){const dossier=document.createElement('button');dossier.className='secondary';dossier.textContent='LC-Akte herunterladen';dossier.onclick=()=>{location.href=`/api/lcs/${activeLc.id}/dossier`};const report=document.createElement('button');report.className='secondary';report.textContent='Prüfbericht PDF';report.onclick=downloadCheckReport;refresh.before(dossier,report)}const upload=$('#uploadBtn');if(!upload||currentUser.role==='VIEWER')return;const invoice=document.createElement('button');invoice.id='createInvoice';invoice.className='secondary';invoice.textContent='+ Handelsrechnung';invoice.onclick=()=>openDocumentCreation('COMMERCIAL_INVOICE');const packing=document.createElement('button');packing.id='createPacking';packing.className='secondary';packing.textContent='+ Packliste';packing.onclick=()=>openDocumentCreation('PACKING_LIST');upload.before(invoice,packing)};
function amendmentChangeHtml(amendment){const changes=[['Warenbeschreibung (45B)',amendment.changedGoods],['Dokumentenanforderungen (46B)',amendment.changedDocuments],['Zusatzbedingungen (47B)',amendment.changedConditions]].filter(([,value])=>value);return changes.length?`<div class="amendment-changes">${changes.map(([label,value])=>`<small class="check-source"><strong>${label}</strong>${esc(value)}</small>`).join('')}</div>`:'<small>Keine inhaltlichen Änderungen in 45B, 46B oder 47B.</small>'}
function reviewGate(review){const status=review.status||(review.discrepancies?'RED':review.warnings?'YELLOW':'GREEN'),copy={GREEN:['Prüfung abgeschlossen','Keine offenen Hinweise oder Abweichungen.'],YELLOW:['Prüfung offen',`${review.warnings} Hinweise müssen noch geprüft werden.`],RED:['Abweichungen vorhanden',`${review.discrepancies} Abweichungen erfordern eine Entscheidung.`]}[status];return `<div class="training-gate gate-${status.toLowerCase()}"><span class="traffic-light tls-${status.toLowerCase()}"><i class="red"></i><i class="yellow"></i><i class="green"></i></span><div><b>${copy[0]}</b><small>${copy[1]}</small></div></div>`}
const showWithAmendmentContent=show;show=async function(id){await showWithAmendmentContent(id);const sections=[...document.querySelectorAll('#detail .docs')],history=sections.find(section=>section.querySelector('h3')?.textContent==='Amendment-Historie');if(!history)return;const amendments=await json(`/api/lcs/${id}/amendments`).catch(()=>[]),cards=history.querySelectorAll('.card');amendments.forEach((amendment,index)=>{if(cards[index])cards[index].insertAdjacentHTML('beforeend',amendmentChangeHtml(amendment))})};
const showWithAssignment=show;show=async function(id){await showWithAssignment(id);const grid=$('#detail .detailbody > .grid');if(!grid||!activeLc)return;grid.insertAdjacentHTML('afterbegin',`<div class="card"><small>Bearbeiter</small><b>${esc(activeLc.assignedTo||'Nicht zugewiesen')}</b></div><div class="card"><small>Wiedervorlage</small><b>${esc(fmtDate(activeLc.followUpDate))}</b></div>`)};
function timelineHtml(entries){return entries.length?entries.map(entry=>`<article class="timeline-entry ${entry.type.toLowerCase()}"><span class="timeline-dot"></span><div><b>${esc(entry.type==='NOTE'?'Aktennotiz':auditLabels[entry.action]||entry.action)}</b><p>${esc(entry.text||'–')}</p><small>${esc(entry.username)} · ${new Intl.DateTimeFormat('de-DE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(entry.occurredAt))}</small></div></article>`).join(''):'<div class="empty compact">Noch keine Einträge in dieser Akte.</div>'}
function activateDossierSection(name){document.querySelectorAll('.dossier-nav button').forEach(button=>button.classList.toggle('active',button.dataset.section===name));document.querySelectorAll('.dossier-section').forEach(section=>section.classList.toggle('active',section.dataset.section===name))}
async function structureDossier(id){const body=$('#detail .detailbody');if(!body||body.querySelector('.dossier-shell'))return;const children=[...body.children],sections={overview:document.createElement('section'),documents:document.createElement('section'),checks:document.createElement('section'),history:document.createElement('section'),admin:document.createElement('section')};Object.entries(sections).forEach(([name,section])=>{section.className='dossier-section';section.dataset.section=name});sections.overview.innerHTML='<div class="sectionhead"><div><h3>Aktenübersicht</h3><p>Die wichtigsten fachlichen Anforderungen dieses Akkreditivs.</p></div></div>';let target=sections.admin;for(const child of children){const title=child.querySelector?.('h3')?.textContent;if(child.classList.contains('grid'))target=sections.admin;else if(title==='Dokumentenakte')target=sections.documents;else if(title==='Automatische Prüfung')target=sections.checks;else if(title==='Erforderliche Dokumente laut LC')target=sections.overview;else if(title==='Amendment-Historie'||child.classList.contains('additional-details'))target=sections.admin;target.append(child)}const timeline=await json(`/api/lcs/${id}/timeline`).catch(()=>[]);sections.history.innerHTML=`<div class="sectionhead"><div><h3>Verlauf & Notizen</h3><p>Chronologische Bearbeitungshistorie dieser LC-Akte.</p></div>${activeLc.followUpDate&&currentUser.role!=='VIEWER'?'<button type="button" id="completeFollowUp" class="secondary">Wiedervorlage erledigt</button>':''}</div>${currentUser.role!=='VIEWER'?'<form id="noteForm" class="note-form"><textarea name="content" maxlength="2000" required placeholder="Fachliche Notiz zur Akte hinzufügen …"></textarea><button type="submit">Notiz speichern</button></form>':''}<div id="timelineList" class="timeline-list">${timelineHtml(timeline)}</div>`;const shell=document.createElement('div');shell.className='dossier-shell';shell.innerHTML=`<aside class="dossier-nav"><b>LC-Akte</b><button type="button" data-section="overview">Übersicht</button><button type="button" data-section="documents">Dokumentenakte</button><button type="button" data-section="checks">Prüfung</button><button type="button" data-section="history">Verlauf & Notizen</button><span></span><button type="button" data-section="admin">Administration</button></aside><div class="dossier-content"></div>`;Object.values(sections).forEach(section=>shell.querySelector('.dossier-content').append(section));body.append(shell);shell.querySelectorAll('.dossier-nav button').forEach(button=>button.onclick=()=>activateDossierSection(button.dataset.section));$('#noteForm')?.addEventListener('submit',async event=>{event.preventDefault();const content=new FormData(event.target).get('content');try{await json(`/api/lcs/${id}/notes`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content})});event.target.reset();const entries=await json(`/api/lcs/${id}/timeline`);$('#timelineList').innerHTML=timelineHtml(entries)}catch(e){alert('Notiz konnte nicht gespeichert werden: '+e.message)}});$('#completeFollowUp')?.addEventListener('click',async()=>{try{await json(`/api/lcs/${id}/follow-up/complete`,{method:'POST'});await load();await show(id);activateDossierSection('history')}catch(e){alert('Wiedervorlage konnte nicht erledigt werden: '+e.message)}});activateDossierSection('overview')}
const showWithDossierNavigation=show;show=async function(id){await showWithDossierNavigation(id);await structureDossier(id)};
function taskRows(tasks){return tasks.length?tasks.map(task=>`<div class="task-row ${task.completed?'completed':''}"><button type="button" class="task-toggle" data-task-toggle="${task.id}" data-task-completed="${task.completed}">${task.completed?'✓':'○'}</button><div><b>${esc(task.title)}</b><small>${task.dueDate?'Fällig '+esc(fmtDate(task.dueDate)):'Keine Fälligkeit'} · ${esc(task.assignedTo||'Nicht zugewiesen')}</small></div>${currentUser.role!=='VIEWER'?`<button type="button" class="ghost danger-text" data-task-delete="${task.id}">Löschen</button>`:''}</div>`).join(''):'<div class="empty compact">Noch keine Aufgaben in dieser Akte.</div>'}
async function enhanceTaskSection(id){const content=$('#detail .dossier-content'),nav=$('#detail .dossier-nav');if(!content||!nav||content.querySelector('[data-section="tasks"]'))return;const tasks=await json(`/api/lcs/${id}/tasks`).catch(()=>[]),section=document.createElement('section');section.className='dossier-section';section.dataset.section='tasks';section.innerHTML=`<div class="sectionhead"><div><h3>Aufgaben</h3><p>Fachliche Arbeitsschritte und Termine dieser Akte.</p></div></div>${currentUser.role!=='VIEWER'?`<form id="taskForm" class="task-form"><input name="title" maxlength="500" required placeholder="Neue Aufgabe …"><select name="assignedTo"><option value="">Nicht zugewiesen</option>${assignableUsers.map(user=>`<option value="${esc(user.username)}" ${user.username===currentUser.username?'selected':''}>${esc(user.displayName)}</option>`).join('')}</select><input name="dueDate" type="date"><button type="submit">Aufgabe anlegen</button></form>`:''}<div id="taskList" class="task-list">${taskRows(tasks)}</div>`;content.insertBefore(section,content.querySelector('[data-section="history"]'));const button=document.createElement('button');button.type='button';button.dataset.section='tasks';button.textContent='Aufgaben';nav.insertBefore(button,nav.querySelector('[data-section="history"]'));button.onclick=()=>activateDossierSection('tasks');const refreshTasks=async()=>{$('#taskList').innerHTML=taskRows(await json(`/api/lcs/${id}/tasks`));openTasks=await json('/api/tasks/open');renderWorkQueue();bindTaskActions()};const bindTaskActions=()=>{document.querySelectorAll('[data-task-toggle]').forEach(toggle=>toggle.onclick=async()=>{await json(`/api/lcs/${id}/tasks/${toggle.dataset.taskToggle}/complete?completed=${toggle.dataset.taskCompleted!=='true'}`,{method:'PUT'});await refreshTasks()});document.querySelectorAll('[data-task-delete]').forEach(remove=>remove.onclick=async()=>{if(confirm('Aufgabe wirklich löschen?')){await json(`/api/lcs/${id}/tasks/${remove.dataset.taskDelete}`,{method:'DELETE'});await refreshTasks()}})};$('#taskForm')?.addEventListener('submit',async event=>{event.preventDefault();const payload=Object.fromEntries(new FormData(event.target).entries());payload.dueDate=payload.dueDate||null;await json(`/api/lcs/${id}/tasks`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});event.target.elements.title.value='';await refreshTasks()});bindTaskActions()}
const showWithTasks=show;show=async function(id){await showWithTasks(id);await enhanceTaskSection(id)};
function completenessMatrix(review){const entries=(review?.results||[]).filter(result=>['DOCUMENT_PRESENT','MISSING_DOCUMENT','UNCLASSIFIED_REQUIREMENT'].includes(result.code));if(!entries.length)return '<div class="empty compact">Keine strukturierten Dokumentenanforderungen vorhanden.</div>';const rows=entries.map(result=>{const state=result.code==='DOCUMENT_PRESENT'?'present':result.code==='MISSING_DOCUMENT'?'missing':'review',label=result.code==='DOCUMENT_PRESENT'?'Vorhanden':result.code==='MISSING_DOCUMENT'?'Fehlt':'Manuell zuordnen';return `<div class="completeness-row"><span class="completeness-state ${state}">${state==='present'?'✓':state==='missing'?'×':'?'}</span><div><b>${esc(result.lcCondition||result.message)}</b><small>${result.documentName?`Zugeordnet: ${esc(result.documentName)}`:esc(result.message)}</small></div><strong class="completeness-label ${state}">${label}</strong></div>`}).join('');const present=entries.filter(result=>result.code==='DOCUMENT_PRESENT').length,missing=entries.filter(result=>result.code==='MISSING_DOCUMENT').length,reviewCount=entries.length-present-missing;return `<div class="completeness-matrix"><div class="completeness-head"><div><h3>Dokumenten-Vollständigkeit</h3><p>Geforderte Dokumente im Vergleich zur aktuellen LC-Akte.</p></div><div><span class="summary passed">${present} vorhanden</span><span class="summary discrepancy">${missing} fehlen</span><span class="summary warning">${reviewCount} zu prüfen</span></div></div>${rows}</div>`}
const showWithCompleteness=show;show=async function(id){await showWithCompleteness(id);const overview=$('#detail [data-section="overview"]');if(!overview)return;const review=await json(`/api/lcs/${id}/document-checks`).catch(()=>null);overview.querySelector('.sectionhead')?.insertAdjacentHTML('afterend',completenessMatrix(review))};
const showWithRequirementMapping=show;show=async function(id){await showWithRequirementMapping(id);if(currentUser.role==='VIEWER')return;const review=await json(`/api/lcs/${id}/document-checks`).catch(()=>null),entries=(review?.results||[]).filter(result=>['DOCUMENT_PRESENT','MISSING_DOCUMENT','UNCLASSIFIED_REQUIREMENT'].includes(result.code)),rows=document.querySelectorAll('#detail .completeness-row'),types=[['COMMERCIAL_INVOICE','Handelsrechnung'],['PACKING_LIST','Packliste'],['BILL_OF_LADING','Konnossement'],['AIR_WAYBILL','Luftfrachtbrief'],['ROAD_CONSIGNMENT_NOTE','CMR'],['CERTIFICATE_OF_ORIGIN','Ursprungszeugnis'],['INSURANCE_CERTIFICATE','Versicherungszertifikat'],['INSPECTION_CERTIFICATE','Inspektionszertifikat'],['BILL_OF_EXCHANGE','Wechsel'],['BENEFICIARY_CERTIFICATE','Begünstigtenzertifikat'],['QUALITY_CERTIFICATE','Qualitätszertifikat'],['COURIER_RECEIPT','Kurierbeleg'],['ANNEX','Anlage'],['OTHER','Sonstiges']];entries.forEach((entry,index)=>{if(entry.code!=='UNCLASSIFIED_REQUIREMENT'||!rows[index])return;const controls=document.createElement('div');controls.className='mapping-controls';controls.innerHTML=`<select><option value="">Dokumenttyp wählen …</option>${types.map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select><button type="button" class="secondary">Zuordnen</button>`;rows[index].querySelector('.completeness-label')?.replaceWith(controls);controls.querySelector('button').onclick=async()=>{const documentType=controls.querySelector('select').value;if(!documentType)return;await json(`/api/lcs/${id}/document-checks/requirements`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({requirement:entry.lcCondition,documentType})});await show(id);activateDossierSection('overview')}})};
function setupAppNavigation(){const destinations={cockpit:'#cockpitSection',lcs:'#lcSection',imports:'#importsSection'};document.querySelectorAll('[data-app-section]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-app-section]').forEach(item=>item.classList.remove('active'));button.classList.add('active');$(destinations[button.dataset.appSection]).scrollIntoView({behavior:'smooth',block:'start'})});$('#appNavMyWork').onclick=()=>{$('#workQueueFilter').value='mine';applyWorkQueueFilter();$('#workQueueSection').scrollIntoView({behavior:'smooth',block:'start'})};$('#appNavTraining').onclick=()=>$('#trainingBtn').click();$('#appNavImport').onclick=()=>$('#importBtn').click();$('#appNavUsers').onclick=()=>$('#usersBtn').click();$('#appNavAudit').onclick=()=>$('#auditBtn').click();$('#appNavSecurity').onclick=()=>$('#tlsStatusBtn').click();$('#appNavPassword').onclick=()=>$('#passwordBtn').click();$('#appNavLogout').onclick=()=>$('#logoutBtn').click();$('#workQueueFilter').onchange=applyWorkQueueFilter;$('#calendarExport').onclick=()=>{location.href=`/api/calendar.ics?scope=${encodeURIComponent($('#workQueueFilter').value)}`}}
function renderWorkQueue(){const active=data.filter(lc=>!['CLOSED','EXPIRED'].includes(lc.status)),items=active.map(lc=>({lc,deadline:deadlineInfo(lc)})),overdue=items.filter(item=>item.deadline.level==='overdue'),upcoming=items.filter(item=>['urgent','soon'].includes(item.deadline.level)),unassigned=active.filter(lc=>!lc.assignedTo);$('#queueOverdue').textContent=overdue.length;$('#queueUpcoming').textContent=upcoming.length;$('#queueUnassigned').textContent=unassigned.length;const queue=items.filter(item=>['overdue','urgent','soon'].includes(item.deadline.level)||!item.lc.assignedTo).sort((a,b)=>a.deadline.score-b.deadline.score).slice(0,12);$('#workQueueList').innerHTML=queue.length?queue.map(({lc,deadline})=>`<div class="queue-row" data-queue-id="${lc.id}"><span class="queue-priority ${deadline.level}"></span><div><b>${esc(lc.reference)}</b><small>${esc(lc.beneficiary||lc.applicant||'–')}</small></div><div><span class="deadline ${deadline.level}">${esc(deadline.text)}</span><small>${lc.followUpDate?'Wiedervorlage '+esc(fmtDate(lc.followUpDate)):'Fristenüberwachung'}</small></div><div><b>${esc(lc.assignedTo||'Nicht zugewiesen')}</b><small>Bearbeiter</small></div>${!lc.assignedTo&&currentUser.role!=='VIEWER'?`<button type="button" class="secondary" data-assign-id="${lc.id}">Mir zuweisen</button>`:'<button type="button" class="secondary">Akte öffnen</button>'}</div>`).join(''):'<div class="empty compact">Keine dringenden Aufgaben. Alle aktuellen Fristen sind im grünen Bereich.</div>';document.querySelectorAll('[data-queue-id]').forEach(row=>row.onclick=()=>show(row.dataset.queueId));document.querySelectorAll('[data-assign-id]').forEach(button=>button.onclick=async event=>{event.stopPropagation();try{await json(`/api/lcs/${button.dataset.assignId}/assign-to-me`,{method:'POST'});await load()}catch(e){alert('Zuweisung fehlgeschlagen: '+e.message)}})}
const renderWithWorkQueue=render;render=function(){renderWithWorkQueue();renderWorkQueue()};
function appendTaskQueue(){if(!openTasks.length)return;const overdue=openTasks.filter(task=>daysUntil(task.dueDate)<0).length,upcoming=openTasks.filter(task=>{const days=daysUntil(task.dueDate);return days>=0&&days<=7}).length;$('#queueOverdue').textContent=Number($('#queueOverdue').textContent)+overdue;$('#queueUpcoming').textContent=Number($('#queueUpcoming').textContent)+upcoming;const rows=openTasks.slice(0,8).map(task=>{const lc=data.find(item=>item.id===task.letterOfCreditId),days=daysUntil(task.dueDate),level=days<0?'overdue':days<=7?'urgent':'normal';return `<div class="queue-row task-queue-row" data-queue-id="${task.letterOfCreditId}"><span class="queue-priority ${level}"></span><div><b>${esc(lc?.reference||'LC-Akte')}</b><small>Aufgabe</small></div><div><span class="deadline ${level}">${esc(task.title)}</span><small>${task.dueDate?'Fällig '+esc(fmtDate(task.dueDate)):'Keine Fälligkeit'}</small></div><div><b>${esc(task.assignedTo||'Nicht zugewiesen')}</b><small>Bearbeiter</small></div><button type="button" class="secondary">Akte öffnen</button></div>`}).join('');$('#workQueueList').insertAdjacentHTML('afterbegin',rows);document.querySelectorAll('.task-queue-row').forEach(row=>row.onclick=async()=>{await show(row.dataset.queueId);activateDossierSection('tasks')})}
const appendTaskQueueBase=appendTaskQueue;appendTaskQueue=function(){if(openTasks.length)$('#workQueueList .empty')?.remove();appendTaskQueueBase()};
const renderWithTaskQueue=render;render=function(){renderWithTaskQueue();appendTaskQueue()};
function applyWorkQueueFilter(){const mode=$('#workQueueFilter').value,username=(currentUser?.username||'').toLowerCase();document.querySelectorAll('#workQueueList .queue-row').forEach(row=>{let owner='';if(row.classList.contains('task-queue-row')){const index=[...document.querySelectorAll('.task-queue-row')].indexOf(row);owner=openTasks[index]?.assignedTo||''}else owner=data.find(lc=>lc.id===row.dataset.queueId)?.assignedTo||'';const visible=mode==='all'||mode==='mine'&&owner.toLowerCase()===username||mode==='unassigned'&&!owner;row.classList.toggle('filtered-out',!visible)})}
const renderWithPersonalQueue=render;render=function(){renderWithPersonalQueue();$('#navTaskBadge').textContent=openTasks.filter(task=>(task.assignedTo||'').toLowerCase()===(currentUser?.username||'').toLowerCase()).length;applyWorkQueueFilter()};
ensureTrainingUi();setupAppNavigation();init();
